const PAPER_STYLE_KEYS = ["width", "minWidth", "maxWidth", "height", "minHeight", "maxHeight"];
const splitDialogStyles = (styles) => {
  const rootStyles = {};
  const paperStyles = {};
  Object.entries(styles || {}).forEach(([key, value]) => {
    (PAPER_STYLE_KEYS.includes(key) ? paperStyles : rootStyles)[key] = value;
  });
  return { rootStyles, paperStyles };
};
export {
  splitDialogStyles
};
